UPDATE characters SET data = '{"slug":"living-room","name":"Living Room","team":"minion","ability":"You become a Storyteller, but you''re still evil. You cannot make players learn themselves or be subjective for abilities.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Living Room (SCP-002) is a biological living room that hypnotizes prey into entering the room and being devoured and regurgitated into fleshy furniture.","summaryBullets":["The Living Room isn''t a player, and instead is another Storyteller playing a very cruel god.","Once the Living Room draws their character token, they immediately become a Storyteller {{i|(and remain evil)}}.","The Living Room will handle all ability interactions {{i|(except for subjective abilities that are based off an individual viewpoint)}}, and makes all decisions whilst not breaking any rules.","The Living Room is no longer a player despite working for the evil team - they cannot die, be targeted, vote, nominate, or register as anything, just like the regular Storyteller.","The Living Room is allowed to pass along information they learned from the Grimoire.","The Living Room is not allowed to be nominated & executed."],"howToRun":["Once the Living Room receives their character token, immediately and publicly declare that **the Living Room is now in-play and which player it is** - remove their seat and put them by your side. From now on, they are no longer a player that can be interacted with, but they are still on the evil team, and must work towards supporting the Demon and their team. They may see the Grimoire at any time, communicate to players at any time with their information, and they act on behalf of the Storyteller when a player performs their actions and receives their results. However, the Living Room cannot change the game''s setup, break the rules of the game, or break the rules of the characters, they can only change decisions a Storyteller can make subjectively, effectively granting the evil team perfect luck. Additionally, since the Living Room is no longer a player, they cannot be targeted by character abilities, they cannot vote or nominate, and they are not considered alive for the vote requirement, exile requirement, or final day requirement. Lastly, the Living Room cannot force a player to learn themselves with their ability {{i|(Ex. Washerwoman, King, Steward)}}, and they cannot Storytell for subjective abilities {{i|(ex. General, Fisherman)}} - the original Storyteller will handle those subjective abilities."],"quote":"**L' || char(820,781,851,800) || 'I' || char(820,848,843,854) || 'V' || char(820,773,851,841) || 'E' || char(823,787,844,851,837) || '.' || char(824,830,831,819) || ' ' || char(821,787,789,793) || 'L' || char(824,859,841) || 'A' || char(822,768,789,791) || 'U' || char(820,776,776,793) || 'G' || char(820,787,771,809,792) || 'H' || char(821,835,797,791) || '.' || char(820,773,788,792) || ' ' || char(823,843,860) || 'L' || char(821,834,810,828) || 'O' || char(823,786,814,846) || 'V' || char(821,777,856,790) || 'E' || char(823,856,816,845) || '.' || char(820,850,804,800) || '**","iconBy":"le_nuberto","jinxes":[{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Living Room''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"},{"name":"Savant","align":"good","text":"The Living Room will give either the true or false info, whilst the original Storyteller gives the other info.","id":"savant"},{"name":"Red Sea Stone","align":"good","text":"The original Storyteller will handle this ability.","slug":"red-sea-stone"},{"name":"Beachcomber","align":"good","text":"The original Storyteller will handle this ability.","id":"beachcomber_the_bootleggers_anthology"},{"name":"Chimneysweep","align":"good","text":"The Living Room is unaffected by the Chimneysweep & doesn''t think they are a good character.","id":"chimneysweep_darkartists_stuff"}],"firstNight":0,"otherNight":0,"setup":false,"art":"art/living-room.png","jsonId":"livingroom_scp_fragmented_veil","curata":false}' WHERE slug='living-room';
